styles:
/* Cấu hình chung - ROG Theme */
        :root {
            --rog-red: #ff0033;       /* Đỏ ROG chủ đạo */
            --rog-dark: #0b0b0b;      /* Nền siêu tối */
            --text-primary: #ffffff;
            --text-secondary: #b0b0b0;
            --accent-glow: rgba(255, 0, 51, 0.3);
        }

        body {
            font-family: 'Roboto', sans-serif; /* Font body thường */
            background-color: var(--rog-dark);
            color: var(--text-primary);
            line-height: 1.6;
            margin: 0;
            padding: 20px;
        }

        /* Override Font Header theo yêu cầu */
        h1, h2, h3, h4, h5 {
            font-family: 'Roboto Condensed', sans-serif !important;
            font-weight: 700 !important;
            text-transform: uppercase; /* ROG hay dùng chữ in hoa cho tiêu đề */
            letter-spacing: 0.5px;
        }

        /* Container chỉ giữ vai trò canh giữa nội dung, không còn khung viền */
        .blog-container {
            max-width: 800px;
            margin: 0 auto;
            padding: 0;
        }

        /* Typography */
        h1 {
            color: #fff;
            font-size: 2.4rem;
            margin-bottom: 25px;
            border-bottom: 2px solid var(--rog-red);
            padding-bottom: 15px;
            line-height: 1.2;
            text-shadow: 0 0 10px var(--accent-glow);
        }

        h2 {
            color: var(--rog-red);
            margin-top: 50px;
            font-size: 1.8rem;
            border-left: 5px solid #fff; /* Tương phản Đỏ - Trắng */
            padding-left: 20px;
            /* Loại bỏ background gradient để hợp với nền trơn */
            padding-top: 5px;
            padding-bottom: 5px;
        }

        h3 {
            color: #fff;
            margin-top: 30px;
            font-size: 1.4rem;
            border-bottom: 1px solid #333;
            padding-bottom: 5px;
            display: inline-block;
        }

        p {
            margin-bottom: 15px;
            font-size: 1.1rem;
            color: var(--text-secondary);
            text-align: justify;
        }

        strong {
            color: #fff;
            font-weight: 700;
        }
        
        a {
            color: var(--rog-red);
            text-decoration: none;
            transition: all 0.2s;
        }
        
        a:hover {
            text-decoration: underline;
            text-shadow: 0 0 8px var(--accent-glow);
        }

        /* Hình ảnh */
        img {
            max-width: 100%;
            height: auto;
            border: 1px solid #333; /* Giảm độ sáng viền ảnh */
            margin: 25px 0;
            display: block;
            transition: transform 0.3s ease;
        }
        
        img:hover {
            border-color: var(--rog-red);
            box-shadow: 0 0 15px var(--accent-glow);
        }

        /* Khung thông số kỹ thuật - HUD Style */
        .tech-spec {
            background-color: #141414; /* Giữ khung này để làm nổi bật thông số */
            border: 1px solid #333;
            border-left: 4px solid var(--rog-red);
            padding: 20px;
            margin: 25px 0;
            position: relative;
        }
        
        .tech-spec::after {
            content: "ROG LAB TEST";
            position: absolute;
            top: -10px;
            right: 10px;
            background: var(--rog-red);
            color: #fff;
            font-size: 0.7rem;
            padding: 2px 8px;
            font-weight: bold;
            font-family: 'Roboto Condensed', sans-serif;
        }

        .tech-spec p {
            margin: 0;
            color: #dcdcdc;
            font-size: 1rem;
        }

        /* Footer bài viết */
        .blog-footer {
            margin-top: 60px;
            padding-top: 30px;
            border-top: 1px solid #333;
            color: #888;
            text-align: center;
            /* Đã bỏ background footer để đồng bộ */
            padding: 20px;
        }

        /* Responsive */
        @media (max-width: 768px) {
            h1 {
                font-size: 1.8rem;
            }
            h2 {
                font-size: 1.5rem;
            }
        }
